item_scroll_len  EQU $ - item_scroll
item_scroll_w    EQU 8                ; px
item_scroll_h    EQU 8                ; px (rows)
item_scroll_cols EQU 1                 ; byte columns (x2 bytes each)
item_scroll_ax   EQU 0                 ; x-anchor, px left of body origin
item_scroll_ay   EQU 0                 ; y-anchor, px above body origin
